11	#define __ASCENDC_API_REDUCE_H__
12	
13	template <typename T>
14	inline __aicore__ void WholeReduceSumAdapt(const LocalTensor<T> &dstLocal, const LocalTensor<T> &srcLocal,
15	                                           const int32_t mask, const int32_t repeatTimes, const int32_t dstRepStride,
16	                                           const int32_t srcBlkStride, const int32_t srcRepStride, ReduceOrder order,
17	                                           const int32_t k) {
18	  WholeReduceSum(dstLocal, srcLocal, mask, repeatTimes, dstRepStride, srcBlkStride, srcRepStride);
19	}
20	
21	template <typename T>
22	inline __aicore__ void WholeReduceMaxAdapt(const LocalTensor<T> &dstLocal, const LocalTensor<T> &srcLocal,
23	                                           const int32_t mask, const int32_t repeatTimes, const int32_t dstRepStride,
24	                                           const int32_t srcBlkStride, const int32_t srcRepStride, ReduceOrder order,
25	                                           const int32_t k) {
26	  WholeReduceMax(dstLocal, srcLocal, mask, repeatTimes, dstRepStride, srcBlkStride, srcRepStride, order);
27	}
28	
29	template <typename T>
30	inline __aicore__ void WholeReduceMinAdapt(const LocalTensor<T> &dstLocal, const LocalTensor<T> &srcLocal,
31	                                           const int32_t mask, const int32_t repeatTimes, const int32_t dstRepStride,
32	                                           const int32_t srcBlkStride, const int32_t srcRepStride, ReduceOrder order,
33	                                           const int32_t k) {
34	  WholeReduceMin(dstLocal, srcLocal, mask, repeatTimes, dstRepStride, srcBlkStride, srcRepStride, order);
35	}
36	
37	template <typename T>
38	inline __aicore__ void WholeReduceMeanAdapt(const LocalTensor<T> &dstLocal, const LocalTensor<T> &srcLocal,
39	                                            const int32_t mask, const int32_t repeatTimes, const int32_t dstRepStride,
40	                                            const int32_t srcBlkStride, const int32_t srcRepStride, ReduceOrder order,
41	                                            const int32_t k) {
42	  WholeReduceSum(dstLocal, srcLocal, mask, repeatTimes, dstRepStride, srcBlkStride, srcRepStride);
43	  Muls(dstLocal, dstLocal, static_cast<T>(static_cast<float>(1) / static_cast<float>(k)), repeatTimes);
44	}
45	
46	template <typename T,
47	          void (*WholeReduceFunc)(const LocalTensor<T> &dstLocal, const LocalTensor<T> &srcLocal, const int32_t mask,
48	                                  const int32_t repeatTimes, const int32_t dstRepStride, const int32_t srcBlkStride,
49	                                  const int32_t srcRepStride, ReduceOrder order, const int32_t k),
50	          void (*BinaryFunc)(const LocalTensor<T> &dstLocal, const LocalTensor<T> &src0Local,
51	                             const LocalTensor<T> &src1Local, const int32_t &calCount)>
52	inline __aicore__ void ReduceLast(const LocalTensor<T> &dst, const LocalTensor<T> &src, const int32_t m,
53	                                  const int32_t k, const int32_t stride, LocalTensor<uint8_t> &tmp_buf) {
54	  const uint16_t k_repeat_size = ONE_REPEAT_BYTE_SIZE / sizeof(T);
55	  const uint16_t m_repeat_size = MAX_REPEAT_TIMES * sizeof(T) / ONE_BLK_SIZE * ONE_BLK_SIZE / sizeof(T);
56	  int32_t srcRepStride = KernelUtils::BlkNum<T>(stride);
57	  if (m <= m_repeat_size && k <= k_repeat_size && (stride % KernelUtils::BlkSize<T>() == 0)) {
58	    WholeReduceFunc(dst, src, k, m, 1, 1, srcRepStride, ReduceOrder::ORDER_ONLY_VALUE, k);
59	  } else if (m > m_repeat_size && k <= k_repeat_size && (stride % KernelUtils::BlkSize<T>() == 0)) {
60	    for (int i = 0; i < m; i += m_repeat_size) {
61	      WholeReduceFunc(dst[i], src[i * k], k, KernelUtils::Min(m - i, m_repeat_size), 1, 1, srcRepStride,
62	                      ReduceOrder::ORDER_ONLY_VALUE, k);
63	    }
64	  } else if (m < m_repeat_size && k > k_repeat_size && (stride % KernelUtils::BlkSize<T>() == 0)) {
65	    LocalTensor<T> tmp_tensor = tmp_buf[0].template ReinterpretCast<T>();
66	    AscendC::PipeBarrier<PIPE_V>();
67	    WholeReduceFunc(dst, src, k_repeat_size, m, 1, 1, srcRepStride, ReduceOrder::ORDER_ONLY_VALUE, k);
68	    for (int i = k_repeat_size; i < k; i += k_repeat_size) {
69	      AscendC::PipeBarrier<PIPE_V>();
70	      WholeReduceFunc(tmp_tensor, src[i], i + k_repeat_size < k ? k_repeat_size : k - i, m, 1, 1, srcRepStride,
71	                      ReduceOrder::ORDER_ONLY_VALUE, k);
72	      AscendC::PipeBarrier<PIPE_V>();
73	      BinaryFunc(dst, dst, tmp_tensor, m);
74	    }
75	  } else {
76	    ASSERT(false && "Reduce k size not support.");
77	  }
78	}
79	
80	__aicore__ inline int64_t GetCacheID(const int64_t idx) {
81	  return bcnt1(idx ^ (idx + 1)) - 1;
82	}
83	
84	template <typename T,
85	          void (*operatorFunc)(const LocalTensor<T> &, const LocalTensor<T> &, const LocalTensor<T> &, const int32_t &)>
86	__aicore__ inline void CacheUpdate(const LocalTensor<T> &dst, const LocalTensor<T> &src, int64_t index, int64_t dim_a) {
87	  int64_t align_num = ONE_BLK_SIZE / sizeof(T);
88	  int64_t dim_a_align = (dim_a + align_num - 1) / align_num * align_num;
89	  int64_t cache_id = GetCacheID(index);
90	  int64_t cache_offset = cache_id * dim_a_align;
91	  for (uint64_t i = 0; i < cache_id; i++) {
92	    operatorFunc(src, dst[i * dim_a_align], src, dim_a);
93	    AscendC::PipeBarrier<PIPE_V>();
94	  }
95	  AscendC::PipeBarrier<PIPE_V>();
96	  DataCopy(dst[cache_offset], src, dim_a_align);
97	}
98	
99	template <typename T>
100	__aicore__ inline void PreProcessReduceSumInt32ForAR(const LocalTensor<T> &src, const LocalTensor<T> &curr_buff,
101	                                                     uint32_t row, uint32_t last, uint32_t pad_last, uint32_t remain,
102	                                                     uint32_t &split_k) {
103	  BinaryRepeatParams default_param;
104	  UnaryRepeatParams default_unary_param;
105	  constexpr uint32_t one_blk_num = ONE_BLK_SIZE / sizeof(T);
106	  if (last >= one_blk_num && remain != 0) {
107	    SetVectorMask<T, MaskMode::COUNTER>(0, split_k);
108	    Adds<T, false>(curr_buff, src[row * pad_last], static_cast<T>(0), MASK_PLACEHOLDER, 1, default_unary_param);
109	    AscendC::PipeBarrier<PIPE_V>();
110	
111	    SetVectorMask<T, MaskMode::COUNTER>(0, remain);
112	    Add<T, false>(curr_buff, curr_buff, src[row * pad_last + split_k], MASK_PLACEHOLDER, 1, default_param);
113	    AscendC::PipeBarrier<PIPE_V>();
114	  } else if (split_k > one_blk_num) {
115	    split_k >>= 1;
116	    SetVectorMask<T, MaskMode::COUNTER>(0, split_k);
117	
118	    Add<T, false>(curr_buff, src[row * pad_last], src[row * pad_last + split_k], MASK_PLACEHOLDER, 1, default_param);
119	    AscendC::PipeBarrier<PIPE_V>();
120	  } else {
121	    SetVectorMask<T, MaskMode::COUNTER>(0, last);
122	    Adds<T, false>(curr_buff, src[row * pad_last], static_cast<T>(0), MASK_PLACEHOLDER, 1, default_unary_param);
123	    AscendC::PipeBarrier<PIPE_V>();
124	  }
125	}
126	
127	template <typename T>
128	__aicore__ inline void ReduceSumByLastAxis(const LocalTensor<T> &dst, const LocalTensor<T> &src,
129	                                           const LocalTensor<T> &tmp, uint32_t first, uint32_t last,
130	                                           uint32_t pad_last) {
131	  constexpr uint32_t one_blk_num = ONE_BLK_SIZE / sizeof(T);
132	  constexpr uint32_t one_rpt_num = ONE_REPEAT_BYTE_SIZE / sizeof(T);
133	
134	  BinaryRepeatParams default_param;
135	  UnaryRepeatParams default_unary_param;
136	  BrcbRepeatParams default_brcb_param;
137	  LocalTensor<T> res_before_gather = tmp[one_rpt_num];
138	  LocalTensor<T> final_res_stored = res_before_gather;
139	
140	  uint32_t k = AscendC::Internal::FindClosestPowerOfTwo(last);
141	  uint32_t split_k = 1 << k;
142	  uint32_t remain = last - split_k;
143	  SetMaskCount();
144	  AscendC::CheckTmpBufferSize(tmp.GetSize(), 0, tmp.GetSize());
145	  for (uint32_t j = 0; j < first; j++) {
146	    uint32_t split_k_copy = split_k;
147	    LocalTensor<T> tmp_row_res = res_before_gather[j * one_blk_num];
148	    LocalTensor<T> tmp_dst = res_before_gather[j * one_blk_num];
149	
150	    PreProcessReduceSumInt32ForAR(src, tmp_row_res, j, last, pad_last, remain, split_k_copy);
151	
152	    while (split_k_copy > one_blk_num) {
153	      split_k_copy >>= 1;
154	      SetVectorMask<T, MaskMode::COUNTER>(0, split_k_copy);
155	
156	      Add<T, false>(tmp_row_res, tmp_row_res, tmp_row_res[split_k_copy], MASK_PLACEHOLDER, 1, default_param);
157	      AscendC::PipeBarrier<PIPE_V>();
158	    }
159	
160	    Brcb(tmp, tmp_row_res, 1, default_brcb_param);
161	    AscendC::PipeBarrier<PIPE_V>();
162	    uint32_t final_tail = last < one_blk_num ? split_k : one_blk_num;
163	    if (split_k != last && final_tail < one_blk_num) {
164	      SetVectorMask<T, MaskMode::COUNTER>(0, remain * one_blk_num);
165	      Add<T, false>(tmp, tmp, tmp[split_k * one_blk_num], MASK_PLACEHOLDER, 1, default_param);
166	      AscendC::PipeBarrier<PIPE_V>();
167	    }
168	    while (final_tail > 1) {
169	      final_tail >>= 1;
170	      SetVectorMask<T, MaskMode::COUNTER>(0, final_tail * one_blk_num);
171	
172	      Add<T, false>(tmp, tmp, tmp[final_tail * one_blk_num], MASK_PLACEHOLDER, 1, default_param);
173	      AscendC::PipeBarrier<PIPE_V>();
174	    }
175	    SetVectorMask<T, MaskMode::COUNTER>(0, one_blk_num);
176	    Adds<T, false>(tmp_dst, tmp, static_cast<T>(0), MASK_PLACEHOLDER, 1, default_unary_param);
177	    AscendC::PipeBarrier<PIPE_V>();
178	  }
179	  LocalTensor<uint32_t> tmp_int = tmp.template ReinterpretCast<uint32_t>();
180	  Duplicate(tmp_int, 1u, one_rpt_num);
181	  AscendC::PipeBarrier<PIPE_V>();
182	  GatherMaskParams gather_mask_param = {1, static_cast<uint16_t>(first), 1, 0};
183	  uint64_t rsvd_cnt;
184	  GatherMask(dst, final_res_stored, tmp_int, true, one_blk_num, gather_mask_param, rsvd_cnt);
185	}
186	
187	template <class T, class pattern, bool isReuseSource = false>
188	__aicore__ inline void ReduceSumInt32(const LocalTensor<T> &dst, const LocalTensor<T> &src,
189	                                      const LocalTensor<uint8_t> &tmp, const uint32_t src_shape[], bool src_inner_pad) {
190	  static_assert(SupportType<pattern, Pattern::Reduce::AR, Pattern::Reduce::RA>(),
191	                "failed to check the reduce pattern, it only supports AR/RA pattern");
192	  static_assert(SupportType<T, int32_t>(), "failed to check the data type, current api supports data type is int32_t");
193	
194	  uint32_t last = src_shape[1];
195	  uint32_t first = src_shape[0];
196	  constexpr uint32_t one_blk_num = ONE_BLK_SIZE / sizeof(T);
197	  uint32_t pad_last = AlignUp(last, one_blk_num);
198	  LocalTensor<T> tmp_dst = tmp.ReinterpretCast<T>();
199	  if constexpr (IsSameType<pattern, Pattern::Reduce::AR>::value) {
200	    ASCENDC_ASSERT((dst.GetSize() >= first), {
201	      KERNEL_LOG(KERNEL_ERROR, "dstTensor must be greater than or equal to %u, current size if %u", first,
202	                 dst.GetSize());
203	    });
204	    ReduceSumByLastAxis(dst, src, tmp_dst, first, last, pad_last);
205	  } else {
206	    AscendC::Internal::BinaryReduceByFirstAxis<T, false, Add<T, false>>(dst, src, tmp_dst, first, last, pad_last);
207	  }
208	  SetMaskNorm();
209	  ResetMask();
210	}
211	
212	#endif  // __ASCENDC_API_REDUCE_H__
