10	#ifndef __ASCENDC_API_BROADCAST_H__
11	#define __ASCENDC_API_BROADCAST_H__
12	
13	constexpr uint32_t BRCB_ONE_SIZE_A = 8;
14	constexpr uint32_t BRCB_HALF_MAX_REPEATE_TIMES_A = 254;
15	constexpr uint32_t BRCB_FLOAT_MAX_REPEATE_TIMES_A = 255;
16	constexpr uint32_t GATHER_MASK_PATTERN_A = 7;
17	
18	template <typename T>
19	inline __aicore__ void BroadcastFirstDim(const LocalTensor<T> &dst, const LocalTensor<T> &src, const uint32_t src_m,
20	                                         const uint32_t src_k, const uint32_t src_z, const uint32_t dst_m,
21	                                         const uint32_t dst_k, const uint32_t dst_z, LocalTensor<uint8_t> &tmp_buf) {
22	  uint32_t dst_inner_offset = dst_k * (src_z == 0 ? 1 : src_z);
23	  uint32_t one_blk_num = KernelUtils::BlkSize<T>();
24	  AscendC::SetMaskCount();
25	  if (dst_inner_offset <= one_blk_num) {
26	    uint32_t total_count = dst_m * dst_inner_offset;
27	    AscendC::SetVectorMask<T, MaskMode::COUNTER>(total_count);
28	    AscendC::CopyRepeatParams repeat_params{1, 0, 1, 0};
29	    AscendC::Copy<T, false>(dst, src, MASK_PLACEHOLDER, 1, repeat_params);
30	  } else {
31	    const uint32_t max_rpt_cnt = dst_m / MAX_REPEAT_TIME;
32	    uint32_t calc_size = 0;
33	    AscendC::SetVectorMask<T, MaskMode::COUNTER>(dst_inner_offset);
34	    const uint16_t dst_rpt_stride = dst_inner_offset * sizeof(T) / ONE_BLK_SIZE;
35	    AscendC::CopyRepeatParams repeat_params{1, 1, dst_rpt_stride, 0};
36	    const uint32_t max_rpt_calc_num = dst_inner_offset * MAX_REPEAT_TIME;
37	    for (uint32_t idx = 0; idx < max_rpt_cnt; idx++) {
38	      AscendC::Copy<T, false>(dst[calc_size], src, MASK_PLACEHOLDER, MAX_REPEAT_TIME, repeat_params);
39	      calc_size += max_rpt_calc_num;
40	    }
41	    uint32_t tail_rpt_times = dst_m - max_rpt_cnt * MAX_REPEAT_TIME;
42	    if (tail_rpt_times != 0) {
43	      AscendC::Copy<T, false>(dst[calc_size], src, MASK_PLACEHOLDER, tail_rpt_times, repeat_params);
44	    }
45	  }
46	  AscendC::SetMaskNorm();
47	  AscendC::ResetMask();
48	}
49	
50	template <typename T>
51	inline __aicore__ void BroadcastMiddleDim(const LocalTensor<T> &dst, const LocalTensor<T> &src, const uint32_t src_m,
52	                                          const uint32_t src_k, const uint32_t src_z, const uint32_t dst_m,
53	                                          const uint32_t dst_k, const uint32_t dst_z, LocalTensor<uint8_t> &tmp_buf) {
54	  uint32_t inner_offset = src_z == 0 ? 1 : src_z;
55	  uint32_t dst_inner_offset = dst_k * inner_offset;
56	  constexpr uint32_t one_blk_num = ONE_BLK_SIZE / sizeof(T);
57	  constexpr uint32_t outer_dim_max_loop = MAX_REPEAT_TIME * one_blk_num;
58	  const uint32_t src_inner_offset = src_k * inner_offset;
59	  if (src_inner_offset >= outer_dim_max_loop) {
60	    for (uint32_t i = 0; i < dst_m; i++) {
61	      AscendC::DataCopy(dst[i * dst_inner_offset], src, dst_inner_offset);
62	    }
63	    AscendC::PipeBarrier<PIPE_V>();
64	  } else {
65	    AscendC::Duplicate(tmp_buf.ReinterpretCast<uint16_t>(), (uint16_t)0, ONE_BLK_SIZE / sizeof(uint16_t));
66	    AscendC::PipeBarrier<PIPE_V>();
67	    int32_t dtype_count = 1;
68	    if constexpr (sizeof(T) == sizeof(float)) {
69	      dtype_count = 2;
70	    }
71	    uint32_t loop_cnt = dst_m / 8U;
72	    uint32_t rpt = dst_inner_offset / one_blk_num;
73	    AscendC::SetMaskNorm();
74	    AscendC::SetVectorMask<uint16_t, MaskMode::NORMAL>(128);
75	    uint32_t dst_blk_stride = dst_inner_offset * dtype_count / 16U;
76	    BinaryRepeatParams binary_params((uint8_t)dst_blk_stride, 0, 0, 1, 1, 0);
77	    uint32_t dst_offset = 0;
78	    for (uint32_t i = 0; i < loop_cnt; i++) {
79	      AscendC::Or<uint16_t, false>(dst[dst_offset].template ReinterpretCast<uint16_t>(),
80	                                   src.template ReinterpretCast<uint16_t>(),
81	                                   tmp_buf.template ReinterpretCast<uint16_t>(), MASK_PLACEHOLDER, rpt, binary_params);
82	      dst_offset += dst_inner_offset * 8;
83	    }
84	    uint32_t loop_tail = dst_m - loop_cnt * 8;
85	    if (loop_tail > 0) {
86	      AscendC::SetMaskNorm();
87	      AscendC::SetVectorMask<uint16_t, MaskMode::NORMAL>(loop_tail * 16);
88	      AscendC::Or<uint16_t, false>(dst[dst_offset].template ReinterpretCast<uint16_t>(),
89	                                   src.template ReinterpretCast<uint16_t>(),
90	                                   tmp_buf.template ReinterpretCast<uint16_t>(), MASK_PLACEHOLDER, rpt, binary_params);
91	    }
92	    AscendC::SetMaskNorm();
93	    AscendC::ResetMask();
94	  }
95	}
96	
97	template <typename T>
98	__aicore__ inline void BrcbSrcToOneBlock(const LocalTensor<T> &src_local, const uint32_t first_dim,
99	                                         uint32_t one_blk_num, LocalTensor<T> &brcb_buf) {
100	  const uint32_t brcb_rpt_times = (first_dim + BRCB_ONE_SIZE_A - 1) / BRCB_ONE_SIZE_A;
101	  uint32_t brcb_max_rpt_times = BRCB_HALF_MAX_REPEATE_TIMES_A;
102	  if constexpr (sizeof(T) == sizeof(float)) {
103	    brcb_max_rpt_times = BRCB_FLOAT_MAX_REPEATE_TIMES_A;
104	  }
105	  const uint32_t loop_cnt = brcb_rpt_times / brcb_max_rpt_times;
106	  const uint32_t tail_rpt = brcb_rpt_times % brcb_max_rpt_times;
107	  uint32_t brcb_src_offset = 0;
108	  uint32_t brcb_dst_offset = 0;
109	  for (uint32_t i = 0; i < loop_cnt; i++) {
110	    Brcb(brcb_buf[brcb_dst_offset], src_local[brcb_src_offset], brcb_max_rpt_times, {1, DEFAULT_REPEAT_STRIDE});
111	    brcb_dst_offset += brcb_max_rpt_times * one_blk_num * BRCB_ONE_SIZE_A;
112	    brcb_src_offset += brcb_max_rpt_times * BRCB_ONE_SIZE_A;
113	  }
114	  if (tail_rpt != 0) {
115	    Brcb(brcb_buf[brcb_dst_offset], src_local[brcb_src_offset], tail_rpt, {1, DEFAULT_REPEAT_STRIDE});
116	  }
117	  AscendC::PipeBarrier<PIPE_V>();
118	}
119	
120	template <typename T>
121	__aicore__ inline void TwoDimBroadCastLastDimAlign(const LocalTensor<T> &dst_local, const LocalTensor<T> &src_local,
122	                                                   LocalTensor<T> &tmp_buf, const uint32_t first_dim,
123	                                                   const uint32_t block_count) {
124	  constexpr uint32_t one_blk_num = ONE_BLK_SIZE / sizeof(T);
125	  BrcbSrcToOneBlock(src_local, first_dim, one_blk_num, tmp_buf);
126	  SetVectorMask<T, MaskMode::COUNTER>(block_count);
127	  const CopyRepeatParams copy_params = {1, 0, (uint16_t)(block_count / one_blk_num), 1};  // overflow check
128	  uint32_t loop_cnt = first_dim / MAX_REPEAT_TIMES;
129	  uint32_t dst_offset = 0;
130	  uint32_t src_offset = 0;
131	  for (uint32_t i = 0; i < loop_cnt; i++) {
132	    Copy<T, false>(dst_local[dst_offset], tmp_buf[src_offset], MASK_PLACEHOLDER, MAX_REPEAT_TIMES, copy_params);
133	    dst_offset += MAX_REPEAT_TIMES * block_count;
134	    src_offset += MAX_REPEAT_TIMES * one_blk_num;
135	  }
136	  uint32_t tail_rpt = first_dim % MAX_REPEAT_TIMES;
137	  if (tail_rpt != 0) {
138	    Copy<T, false>(dst_local[dst_offset], tmp_buf[src_offset], MASK_PLACEHOLDER, tail_rpt, copy_params);
139	  }
140	  AscendC::PipeBarrier<PIPE_V>();
141	}
142	
143	template <typename T>
144	__aicore__ inline void TwoDimBroadCastLastDimNotAlign(const LocalTensor<T> &dst_local, const LocalTensor<T> &src_local,
145	                                                      LocalTensor<T> &tmp_buf, const uint32_t first_dim,
146	                                                      const uint32_t block_count) {
147	  constexpr uint32_t one_blk_num = ONE_BLK_SIZE / sizeof(T);
148	  BrcbSrcToOneBlock(src_local, first_dim, one_blk_num, tmp_buf);
149	  const uint32_t align_blk_num = (block_count + one_blk_num - 1) / one_blk_num;
150	  const uint32_t block_count_align = align_blk_num * one_blk_num;
151	  SetVectorMask<T, MaskMode::COUNTER>(block_count_align);
152	  const CopyRepeatParams copy_params = {1, 0, (uint16_t)align_blk_num, 1};
153	  uint32_t copy_counts = first_dim / MAX_REPEAT_TIMES;
154	  uint32_t dst_offset = 0;
155	  uint32_t src_offset = 0;
156	  auto copy_tmp_buffer = tmp_buf[first_dim * one_blk_num];
157	  for (uint32_t i = 0; i < copy_counts; i++) {
158	    Copy<T, false>(copy_tmp_buffer[dst_offset], tmp_buf[src_offset], MASK_PLACEHOLDER, MAX_REPEAT_TIMES, copy_params);
159	    dst_offset += MAX_REPEAT_TIMES * block_count_align;
160	    src_offset += MAX_REPEAT_TIMES * one_blk_num;
161	  }
162	  uint32_t tail_rpt = first_dim % MAX_REPEAT_TIMES;
163	  if (tail_rpt != 0) {
164	    Copy<T, false>(copy_tmp_buffer[dst_offset], tmp_buf[src_offset], MASK_PLACEHOLDER, tail_rpt, copy_params);
165	  }
166	  AscendC::PipeBarrier<PIPE_V>();
167	  const GatherMaskParams gather_params = {1, (uint16_t)first_dim, (uint16_t)align_blk_num, 0};  // uint32 cast to uint16
168	  uint64_t rsvd_cnt = 0;
169	  GatherMask(dst_local, copy_tmp_buffer, GATHER_MASK_PATTERN_A, true, block_count, gather_params, rsvd_cnt);
170	  SetMaskCount();
171	  AscendC::PipeBarrier<PIPE_V>();
172	}
173	
174	template <typename T>
175	__aicore__ inline void GetBrcAlignLoopNumbers(const uint32_t first_dim, const uint32_t block_count,
176	                                              const uint32_t tmp_buf_size, uint32_t &one_repeat_size, uint32_t &range_m,
177	                                              uint32_t &tail_m) {
178	  constexpr uint32_t one_blk_num = ONE_BLK_SIZE / sizeof(T);
179	  constexpr uint32_t min_brcb_temp_buffer_size = one_blk_num * one_blk_num + one_blk_num;
180	  constexpr uint32_t min_tmp_buf_size = min_brcb_temp_buffer_size;
181	  ASCENDC_ASSERT((tmp_buf_size >= min_tmp_buf_size), {
182	    KERNEL_LOG(KERNEL_ERROR,
183	               "tmp_buf_size can't smaller than min_tmp_buf_size, tmp_buf_size is %u, min_tmp_buf_size is %u!",
184	               tmp_buf_size, min_tmp_buf_size);
185	  });
186	  one_repeat_size = tmp_buf_size / min_tmp_buf_size * one_blk_num;
187	  range_m = first_dim / one_repeat_size;
188	  tail_m = first_dim - one_repeat_size * range_m;
189	}
190	
191	template <typename T>
192	__aicore__ inline void GetBrcNotAlignLoopNumbers(const uint32_t first_dim, const uint32_t block_count,
193	                                                 const uint32_t tmp_buf_size, uint32_t &one_repeat_size,
194	                                                 uint32_t &range_m, uint32_t &tail_m) {
195	  constexpr uint32_t one_blk_num = ONE_BLK_SIZE / sizeof(T);
196	  constexpr uint32_t min_brcb_temp_buffer_size = one_blk_num * one_blk_num + one_blk_num;
197	  const uint32_t align_blk_num = (block_count + one_blk_num - 1) / one_blk_num;
198	  const uint32_t block_count_align = align_blk_num * one_blk_num;
199	  const uint32_t min_copy_temp_buffer_size = one_blk_num * block_count_align;
200	  const uint32_t min_tmp_buf_size = min_brcb_temp_buffer_size + min_copy_temp_buffer_size;
201	  ASCENDC_ASSERT((tmp_buf_size >= min_tmp_buf_size), {
202	    KERNEL_LOG(KERNEL_ERROR,
203	               "tmp_buf_size can't smaller than min_tmp_buf_size, tmp_buf_size is %u, min_tmp_buf_size is %u!",
204	               tmp_buf_size, min_tmp_buf_size);
205	  });
206	  one_repeat_size = tmp_buf_size / min_tmp_buf_size * one_blk_num;
207	  range_m = first_dim / one_repeat_size;
208	  tail_m = first_dim - one_repeat_size * range_m;
209	}
210	
211	template <typename T>
212	inline __aicore__ void GetSrcTensorWithoutStride(const LocalTensor<T> &tmp_src, const LocalTensor<T> &src,
213	                                                 const uint32_t cal_cnt, const uint32_t offset) {
214	  uint64_t src_offset = 0;
215	  event_t event_id_v_to_s = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_S));
216	  event_t event_id_s_to_v = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::S_V));
217	  AscendC::SetFlag<HardEvent::V_S>(event_id_v_to_s);
218	  AscendC::WaitFlag<HardEvent::V_S>(event_id_v_to_s);
219	  for (uint32_t i = 0; i < cal_cnt; i++) {
220	    auto tmp = src.GetValue(src_offset);
221	    tmp_src.SetValue(i, tmp);
222	    src_offset += offset;
223	  }
224	  AscendC::SetFlag<HardEvent::S_V>(event_id_s_to_v);
225	  AscendC::WaitFlag<HardEvent::S_V>(event_id_s_to_v);
226	}
227	
228	template <typename T>
229	inline __aicore__ void BroadcastWithStride(const LocalTensor<T> &dst, const LocalTensor<T> &src, const uint32_t src_m,
230	                                           const uint32_t src_k, const uint32_t src_z, const uint32_t dst_m,
231	                                           const uint32_t dst_k, const uint32_t dst_z, LocalTensor<T> &tmp_buf) {
232	  uint32_t one_repeat_size = 0;
233	  uint32_t range_m = 0;
234	  uint32_t tail_m = 0;
235	  uint64_t dst_offset = 0;
236	  uint64_t src_offset = 0;
237	  if (dst_k * sizeof(T) % ONE_BLK_SIZE == 0) {
238	    GetBrcAlignLoopNumbers<T>(dst_m, dst_k, tmp_buf.GetSize(), one_repeat_size, range_m, tail_m);
239	    LocalTensor<T> tmp_src = tmp_buf;
240	    tmp_src.SetSize(one_repeat_size);
241	    LocalTensor<T> brcb_buf = tmp_buf[one_repeat_size];
242	    for (uint32_t i = 0; i < range_m; i++) {
243	      GetSrcTensorWithoutStride(tmp_src, src[src_offset], one_repeat_size, src_k);
244	      TwoDimBroadCastLastDimAlign(dst[dst_offset], tmp_src, brcb_buf, one_repeat_size, dst_k);
245	      dst_offset += one_repeat_size * dst_k;
246	      src_offset += one_repeat_size * src_k;
247	    }
248	    if (tail_m != 0) {
249	      GetSrcTensorWithoutStride(tmp_src, src[src_offset], tail_m, src_k);
250	      TwoDimBroadCastLastDimAlign(dst[dst_offset], tmp_src, brcb_buf, tail_m, dst_k);
251	    }
252	  } else {
253	    GetBrcNotAlignLoopNumbers<T>(dst_m, dst_k, tmp_buf.GetSize(), one_repeat_size, range_m, tail_m);
254	    LocalTensor<T> tmp_src = tmp_buf;
255	    tmp_src.SetSize(one_repeat_size);
256	    LocalTensor<T> brcb_buf = tmp_buf[one_repeat_size];
257	    for (uint32_t i = 0; i < range_m; i++) {
258	      GetSrcTensorWithoutStride(tmp_src, src[src_offset], one_repeat_size, src_k);
259	      TwoDimBroadCastLastDimNotAlign(dst[dst_offset], tmp_src, brcb_buf, one_repeat_size, dst_k);
260	      dst_offset += one_repeat_size * dst_k;
261	      src_offset += one_repeat_size * src_k;
262	    }
263	    if (tail_m != 0) {
264	      GetSrcTensorWithoutStride(tmp_src, src[src_offset], tail_m, src_k);
265	      TwoDimBroadCastLastDimNotAlign(dst[dst_offset], tmp_src, brcb_buf, tail_m, dst_k);
266	    }
267	  }
268	}
269	
270	template <typename T>
271	inline __aicore__ void BroadcastMiddleDimWithCopy(const LocalTensor<T> &dst, const LocalTensor<T> &src,
272	                                                  const uint32_t src_m, const uint32_t src_k, const uint32_t src_z,
273	                                                  const uint32_t dst_m, const uint32_t dst_k, const uint32_t dst_z,
274	                                                  LocalTensor<uint8_t> &tmp_buf, const uint32_t last_dim_stride = 1) {
275	  const uint32_t max_rpt_cnt = dst_m / MAX_REPEAT_TIME;
276	  uint32_t calc_size = 0;
277	  const uint32_t dst_inner_offset = dst_k * dst_z;
278	  AscendC::SetMaskCount();
279	  AscendC::SetVectorMask<T, MaskMode::COUNTER>(dst_inner_offset);
280	  const uint16_t dst_rpt_stride = dst_inner_offset * sizeof(T) / ONE_BLK_SIZE;
281	  const uint32_t max_rpt_calc_num = dst_inner_offset * MAX_REPEAT_TIME;
282	  AscendC::CopyRepeatParams repeat_params{1, 0, dst_rpt_stride, 1};
283	  for (uint32_t idx = 0; idx < max_rpt_cnt; idx++) {
284	    AscendC::Copy<T, false>(dst[calc_size], src, MASK_PLACEHOLDER, MAX_REPEAT_TIME, repeat_params);
285	    calc_size += max_rpt_calc_num;
286	  }
287	  uint32_t tail_rpt_times = dst_m - max_rpt_cnt * MAX_REPEAT_TIME;
288	  if (tail_rpt_times != 0) {
289	    AscendC::Copy<T, false>(dst[calc_size], src, MASK_PLACEHOLDER, tail_rpt_times, repeat_params);
290	  }
291	  AscendC::SetMaskNorm();
292	  AscendC::ResetMask();
293	}
294	
295	template <typename T>
296	inline __aicore__ void BroadcastCommon(const LocalTensor<T> &dst, const LocalTensor<T> &src, const uint32_t src_m,
297	                                       const uint32_t src_k, const uint32_t src_z, const uint32_t dst_m,
298	                                       const uint32_t dst_k, const uint32_t dst_z, LocalTensor<uint8_t> &tmp_buf,
299	                                       const uint32_t last_dim_stride = 1) {
300	  uint32_t inner_offset = src_z == 0 ? 1 : src_z;
301	  uint32_t dst_inner_offset = dst_k * inner_offset;
302	  if (src_m == 1 && src_k == dst_k && src_z == dst_z) {  //(1,B) ->(A,B) or (1,B,C) ->(A,B,C)
303	    BroadcastFirstDim(dst, src, src_m, src_k, src_z, dst_m, dst_k, dst_z, tmp_buf);
304	  } else if ((src_k == 1) && (src_m == dst_m) && (src_z == dst_z)) {
305	    if (src_z == 0) {  // (A,1) -> (A,B)
306	      if (last_dim_stride > 1) {
307	        LocalTensor<T> tmp_t_buf = tmp_buf.template ReinterpretCast<T>();
308	        AscendC::SetMaskCount();
309	        BroadcastWithStride(dst, src, src_m, last_dim_stride, src_z, dst_m, dst_k, dst_z, tmp_t_buf);
310	        AscendC::SetMaskNorm();
311	        AscendC::ResetMask();
312	      } else {
313	        const uint32_t dst_shape[2]{dst_m, dst_k};
314	        const uint32_t src_shape[2]{src_m, src_k};
315	        AscendC::Broadcast<T, 2, 1>(dst, src, dst_shape, src_shape, tmp_buf);
316	      }
317	    } else {  // (A,1,C) -> (A,B,C)
318	      if (dst_z <= KernelUtils::BlkSize<T>()) {
319	        BroadcastMiddleDimWithCopy(dst, src, src_m, src_k, src_z, dst_m, dst_k, dst_z, tmp_buf);
320	      } else {
321	        for (int i = 0; i < src_m; i++) {
322	          BroadcastMiddleDim(dst[i * dst_inner_offset], src[i * src_z], src_k, src_z, 0, dst_k, dst_z, 0, tmp_buf);
323	        }
324	      }
325	    }
326	  } else if (src_k == 1 && src_m == 1 && src_z == 0 && dst_z == 0) {  // (1,1) -> (A,B)
327	    const uint32_t dst_shape[2]{dst_m, dst_k};
328	    const uint32_t src_shape[2]{src_m, src_k};
329	    AscendC::Broadcast<T, 2, 1>(dst, src, dst_shape, src_shape, tmp_buf);
330	  } else {
331	    ASSERT(false && "Broadcast size not support.");
332	  }
333	}
334	
335	template <typename T>
336	inline __aicore__ void BroadcastWithCast(const LocalTensor<T> &dst, const LocalTensor<T> &src, const uint32_t src_m,
337	                                         const uint32_t src_k, const uint32_t src_z, const uint32_t dst_m,
338	                                         const uint32_t dst_k, const uint32_t dst_z, LocalTensor<uint8_t> &tmp_buf,
339	                                         const uint32_t last_dim_stride = 1) {
340	  if (src_z != dst_z) {
341	    ASSERT(false && "Broadcast inner_axis mismatch is not supported.");
342	  }
343	  LocalTensor<half> dup_tmp = tmp_buf.template ReinterpretCast<half>();
344	  if (src_m == 1 && src_k == dst_k) {  //(1,B) ->(A,B) or (1,B,C) ->(A,B,C)
345	    uint32_t inner_offset = src_z == 0 ? 1 : src_z;
346	    constexpr uint32_t kRatio = sizeof(uint16_t) / sizeof(T);
347	    uint32_t dst_inner_offset = dst_k * inner_offset / kRatio;
348	    LocalTensor<uint16_t> src_tmp = src.template ReinterpretCast<uint16_t>();
349	    LocalTensor<uint16_t> dst_tmp = dst.template ReinterpretCast<uint16_t>();
350	    BroadcastFirstDim(dst_tmp, src_tmp, src_m, dst_inner_offset, 0, dst_m, dst_inner_offset, 0, tmp_buf);
351	  } else if (src_k == 1 && src_m == dst_m) {
352	    if (src_z == 0) {
353	      const uint32_t dst_shape[2]{dst_m, dst_k};
354	      const uint32_t src_shape[2]{src_m, src_k};
355	      AscendC::Broadcast<T, 2, 1>(dst, src, dst_shape, src_shape, tmp_buf);
356	    } else {
357	      const uint8_t scalar = 0.0;
358	      const uint32_t dst_shape[2]{dst_k, dst_z};
359	      const uint32_t src_shape[2]{src_k, src_z};
360	      uint32_t inner_offset = src_z == 0 ? 1 : src_z;
361	      uint32_t dst_inner_offset = dst_k * inner_offset;
362	      for (int i = 0; i < src_m; i++) {
363	        AscendC::Broadcast<T, 2, 0>(dst[i * dst_inner_offset], src[i * inner_offset], dst_shape, src_shape, tmp_buf);
364	      }
365	    }
366	  } else if (src_k == 1 && src_m == 1 && src_z == 0 && dst_z == 0) {  // (1,1) -> (A,B)
367	    const uint32_t src_shape[2]{src_m, src_k};
368	    const uint32_t dst_shape[2]{dst_m, dst_k};
369	    AscendC::Broadcast<T, 2, 1>(dst, src, dst_shape, src_shape, tmp_buf);
370	  } else {
371	    ASSERT(false && "Broadcast size not support.");
372	  }
373	}
374	
375	inline __aicore__ void BroadcastInt64LastDim(const LocalTensor<int32_t> &dst_int32,
376	                                             const LocalTensor<int32_t> &src_int32, const uint32_t src_m,
377	                                             const uint32_t src_k, const uint32_t src_z, const uint32_t dst_m,
378	                                             const uint32_t dst_k, const uint32_t dst_z, LocalTensor<int32_t> &calc_buf,
379	                                             const uint32_t last_dim_stride = 1) {
380	  constexpr uint32_t ONE_LOOP_CALC_NUM = 2;
381	  auto event_id_vs = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_S));
382	  auto event_id = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::S_V));
383	  AscendC::SetMaskNorm();
384	  const uint32_t loop_cnt = src_m / ONE_LOOP_CALC_NUM;
385	  uint32_t calc_buf_offset = 0;
386	  constexpr uint32_t one_loop_offset = ONE_BLK_SIZE / sizeof(int32_t);
387	  uint32_t src_offset = 0;
388	  AscendC::SetFlag<HardEvent::V_S>(event_id_vs);
389	  AscendC::WaitFlag<HardEvent::V_S>(event_id_vs);
390	  for (uint32_t loop = 0; loop < loop_cnt; loop++) {
391	    int32_t calc_element_1 = src_int32.GetValue(src_offset++);
392	    AscendC::SetFlag<HardEvent::S_V>(event_id);
393	    AscendC::WaitFlag<HardEvent::S_V>(event_id);
394	    AscendC::SetVectorMask<int32_t, MaskMode::NORMAL>(0, 0x55);
395	    AscendC::Duplicate<int32_t, false>(calc_buf[calc_buf_offset], calc_element_1, MASK_PLACEHOLDER, 1, 1, 0);
396	    int32_t calc_element_2 = src_int32.GetValue(src_offset++);
397	    AscendC::SetFlag<HardEvent::S_V>(event_id);
398	    AscendC::WaitFlag<HardEvent::S_V>(event_id);
399	    AscendC::SetVectorMask<int32_t, MaskMode::NORMAL>(0, 0xaa);
400	    AscendC::Duplicate<int32_t, false>(calc_buf[calc_buf_offset], calc_element_2, MASK_PLACEHOLDER, 1, 1, 0);
401	    calc_buf_offset += one_loop_offset;
402	    int32_t calc_element_3 = src_int32.GetValue(src_offset++);
403	    AscendC::SetFlag<HardEvent::S_V>(event_id);
404	    AscendC::WaitFlag<HardEvent::S_V>(event_id);
405	    AscendC::SetVectorMask<int32_t, MaskMode::NORMAL>(0, 0x55);
406	    AscendC::Duplicate<int32_t, false>(calc_buf[calc_buf_offset], calc_element_3, MASK_PLACEHOLDER, 1, 1, 0);
407	    int32_t calc_element_4 = src_int32.GetValue(src_offset++);
408	    AscendC::SetFlag<HardEvent::S_V>(event_id);
409	    AscendC::WaitFlag<HardEvent::S_V>(event_id);
410	    AscendC::SetVectorMask<int32_t, MaskMode::NORMAL>(0, 0xaa);
411	    AscendC::Duplicate<int32_t, false>(calc_buf[calc_buf_offset], calc_element_4, MASK_PLACEHOLDER, 1, 1, 0);
412	    calc_buf_offset += one_loop_offset;
413	  }
414	  const uint32_t remain_cnt = src_m - loop_cnt * ONE_LOOP_CALC_NUM;
415	  if (remain_cnt != 0) {
416	    int32_t calc_element = src_int32.GetValue(src_offset++);
417	    AscendC::SetFlag<HardEvent::S_V>(event_id);
418	    AscendC::WaitFlag<HardEvent::S_V>(event_id);
419	    AscendC::SetVectorMask<int32_t, MaskMode::NORMAL>(0, 0x55);
420	    AscendC::Duplicate<int32_t, false>(calc_buf[calc_buf_offset], calc_element, MASK_PLACEHOLDER, 1, 1, 0);
421	    int32_t calc_element_2 = src_int32.GetValue(src_offset++);
422	    AscendC::SetFlag<HardEvent::S_V>(event_id);
423	    AscendC::WaitFlag<HardEvent::S_V>(event_id);
424	    AscendC::SetVectorMask<int32_t, MaskMode::NORMAL>(0, 0xaa);
425	    AscendC::Duplicate<int32_t, false>(calc_buf[calc_buf_offset], calc_element_2, MASK_PLACEHOLDER, 1, 1, 0);
426	  }
427	  AscendC::PipeBarrier<PIPE_V>();
428	  AscendC::SetMaskCount();
429	  constexpr uint32_t RATIAO = sizeof(int64_t) / sizeof(int32_t);
430	  const uint32_t calc_cnt = dst_k * RATIAO;
431	  AscendC::SetVectorMask<int32_t, MaskMode::COUNTER>(calc_cnt);
432	  AscendC::CopyRepeatParams repeat_params{1, 0, uint16_t(dst_k * sizeof(int64_t) / ONE_BLK_SIZE), 1};
433	  const uint32_t max_repeat_count = src_m / MAX_REPEAT_TIMES;
434	  const uint32_t dst_stride = MAX_REPEAT_TIMES * calc_cnt;
435	  constexpr uint32_t src_stride = MAX_REPEAT_TIMES * ONE_BLK_SIZE / sizeof(int32_t);
436	  uint32_t buf_offset = 0;
437	  uint32_t dst_offset = 0;
438	  for (uint32_t rpt_time = 0; rpt_time < max_repeat_count; rpt_time++) {
439	    AscendC::Copy<int32_t, false>(dst_int32[dst_offset], calc_buf[buf_offset], MASK_PLACEHOLDER, MAX_REPEAT_TIMES,
440	                                  repeat_params);
441	    dst_offset += dst_stride;
442	    buf_offset += src_stride;
443	  }
444	  uint32_t tail_rpt_times = src_m - max_repeat_count * MAX_REPEAT_TIMES;
445	  if (tail_rpt_times > 0) {
446	    AscendC::Copy<int32_t, false>(dst_int32[dst_offset], calc_buf[buf_offset], MASK_PLACEHOLDER, tail_rpt_times,
447	                                  repeat_params);
448	  }
449	}
450	
451	template <typename T>
452	inline __aicore__ void BroadcastInt64(const LocalTensor<T> &dst, const LocalTensor<T> &src, const uint32_t src_m,
453	                                      const uint32_t src_k, const uint32_t src_z, const uint32_t dst_m,
454	                                      const uint32_t dst_k, const uint32_t dst_z, LocalTensor<uint8_t> &tmp_buf,
455	                                      const uint32_t last_dim_stride = 1) {
456	  if (src_z != dst_z) {
457	    ASSERT(false && "Broadcast inner_axis mismatch is not supported.");
458	  }
459	  LocalTensor<int32_t> dst_int32 = dst.template ReinterpretCast<int32_t>();
460	  LocalTensor<int32_t> src_int32 = src.template ReinterpretCast<int32_t>();
461	  constexpr uint32_t kRatio = sizeof(T) / sizeof(int32_t);
462	  uint32_t inner_offset = src_z == 0 ? 1 : src_z;
463	  uint32_t dst_inner_offset = dst_k * inner_offset * kRatio;
464	  if (src_m == 1 && src_k == dst_k) {  //(1,B) ->(A,B) or (1,B,C) ->(A,B,C)
465	    BroadcastFirstDim(dst_int32, src_int32, src_m, dst_inner_offset, 0, dst_m, dst_inner_offset, 0, tmp_buf);
466	  } else if (src_k == 1 && src_m == dst_m) {
467	    if (src_z == 0) {  // (A,1) -> (A,B)
468	      const uint32_t buf_max_calc_num = tmp_buf.GetSize() * sizeof(uint8_t) / ONE_BLK_SIZE;
469	      LocalTensor<int32_t> calc_buf = tmp_buf.template ReinterpretCast<int32_t>();
470	      uint32_t buf_loop_cnt = src_m * src_k / buf_max_calc_num;
471	      uint32_t src_offset = 0;
472	      uint32_t dst_offset = 0;
473	      const uint32_t dst_stride = buf_max_calc_num * dst_inner_offset;
474	      const uint32_t src_stride = buf_max_calc_num * kRatio;
475	      for (uint32_t loop_idx = 0; loop_idx < buf_loop_cnt; loop_idx++) {
476	        BroadcastInt64LastDim(dst_int32[dst_offset], src_int32[src_offset], buf_max_calc_num, src_k, src_z,
477	                              buf_max_calc_num, dst_k, dst_z, calc_buf, last_dim_stride);
478	        dst_offset += dst_stride;
479	        src_offset += src_stride;
480	      }
481	      const uint32_t tail_calc_num = src_m - buf_loop_cnt * buf_max_calc_num;
482	      if (tail_calc_num != 0) {
483	        BroadcastInt64LastDim(dst_int32[dst_offset], src_int32[src_offset], tail_calc_num, src_k, src_z, tail_calc_num,
484	                              dst_k, dst_z, calc_buf, last_dim_stride);
485	      }
486	      AscendC::SetMaskNorm();
487	      AscendC::ResetMask();
488	    } else {  // (A,1,C) -> (A,B,C)
489	      uint32_t dst_offset = 0;
490	      uint32_t src_offset = 0;
491	      const uint32_t src_inner_offset = inner_offset * kRatio;
492	      for (int i = 0; i < src_m; i++) {
493	        const uint32_t dst_shape[2]{dst_k, dst_z * kRatio};
494	        const uint32_t src_shape[2]{src_k, src_z * kRatio};
495	        AscendC::Broadcast<int32_t, 2, 0>(dst_int32[dst_offset], src_int32[src_offset], dst_shape, src_shape, tmp_buf);
496	        dst_offset += dst_inner_offset;
497	        src_offset += src_inner_offset;
498	      }
499	    }
500	  } else if (src_k == 1 && src_m == 1 && src_z == 0 && dst_z == 0) {  // (1,1) -> (A,B)
501	    const T scalarVlue = src.GetValue(0);
502	    auto event_id = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::S_V));
503	    AscendC::SetFlag<HardEvent::S_V>(event_id);
504	    AscendC::WaitFlag<HardEvent::S_V>(event_id);
505	    Duplicate(dst, scalarVlue, dst_m * dst_k, tmp_buf);
506	  } else {
507	    ASSERT(false && "Broadcast size not support.");
508	  }
509	}
510	
511	template <typename T>
512	inline __aicore__ void Broadcast(const LocalTensor<T> &dst, const LocalTensor<T> &src, const uint32_t src_m,
513	                                 const uint32_t src_k, const uint32_t src_z, const uint32_t dst_m, const uint32_t dst_k,
514	                                 const uint32_t dst_z, LocalTensor<uint8_t> &tmp_buf,
515	                                 const uint32_t last_dim_stride = 1) {
516	  if constexpr (AscendC::SupportType<T, int64_t, uint64_t>()) {
517	    BroadcastInt64(dst, src, src_m, src_k, src_z, dst_m, dst_k, dst_z, tmp_buf, last_dim_stride);
518	  } else if constexpr (AscendC::SupportType<T, uint8_t, int8_t>()) {
519	    BroadcastWithCast(dst, src, src_m, src_k, src_z, dst_m, dst_k, dst_z, tmp_buf, last_dim_stride);
520	  } else if constexpr (AscendC::SupportType<T, int16_t, uint16_t, half, float, int32_t, uint32_t>()) {
521	    BroadcastCommon(dst, src, src_m, src_k, src_z, dst_m, dst_k, dst_z, tmp_buf, last_dim_stride);
522	  } else {
523	    ASSERT(false && "Broadcast type not support.");
524	  }
525	}
526	
527	template <typename T>
528	inline __aicore__ void Broadcast(const LocalTensor<T> &dst, const LocalTensor<T> &src, const uint32_t src_m,
529	                                 const uint32_t src_n, const uint32_t src_k, const uint32_t src_z, const uint32_t dst_m,
530	                                 const uint32_t dst_n, const uint32_t dst_k, const uint32_t dst_z,
531	                                 LocalTensor<uint8_t> &tmp_buf, const uint32_t last_dim_stride = 1) {
532	  if (src_m == 1 && src_k == 1 && src_n == dst_n &&
533	      src_z == dst_z) {  // (1,B,1,B) -> (A, B, A, B), broadcast first and third dim
534	    Broadcast(dst, src, src_n, src_k, src_z, dst_n, dst_k, dst_z, tmp_buf);  // (B, 1, B) -> (B, A, B)
535	    AscendC::PipeBarrier<PIPE_V>();
536	    const uint32_t offset = dst_n * dst_k * dst_z;
537	    Broadcast(dst[offset], dst, src_m, offset, 0, dst_m - 1, offset, 0, tmp_buf);  // (1, BAB) -> (A, BAB)
538	  } else if (src_n == 1 && src_z == 1) {  // (A, 1, A, 1) -> (A, B, A, B), broadcast second and fourth dim
539	    const uint32_t offset = dst_m * src_n * dst_k;
540	    ASSERT((tmp_buf.GetSize() > (offset * dst_z + dst_m * dst_n) * sizeof(T)) && "tmp_buf size is not enough.");
541	    LocalTensor<T> inter_buf = tmp_buf.template ReinterpretCast<T>();
542	    inter_buf.SetSize(offset * dst_z);
543	    LocalTensor<uint8_t> left_buf = tmp_buf[offset * dst_z * sizeof(T)];
544	    Broadcast(inter_buf, src, offset, 1, 0, offset, dst_z, 0, left_buf, last_dim_stride);  // (A1A, 1) -> (A1A, B)
545	    AscendC::PipeBarrier<PIPE_V>();
546	    // (A, 1, AB) -> (A, B, AB)
547	    Broadcast(dst, inter_buf, src_m, 1, dst_k * dst_z, dst_m, dst_n, dst_k * dst_z, left_buf);
548	  } else {
549	    ASSERT(false && "Broadcast type not support.");
550	  }
551	}
552	
553	#endif  // __ASCENDC_API_BROADCAST_H__
