192	__aicore__ inline uint64_t FindNearestPower2(const uint64_t value) {
193	  if (value == 0) {
194	    return 0;
195	  } else if (value <= CONST2) {
196	    return CONST1;
197	  } else if (value <= CONST4) {
198	    return CONST2;
199	  } else {
200	    const uint64_t num = value - CONST1;
201	    const uint64_t pow = CONST63 - clz(num);
202	    return (CONST1 << pow);
