40	Status DimensionCollapse(const Tensor &input, const Tensor &output,
41	                         std::vector<std::pair<bool, std::vector<uint32_t>>> &result, uint32_t &broadcast_num) {
42	  if (input.vectorized_axis.size() != output.vectorized_axis.size()) {
43	    GELOGE(af::FAILED, "Codegen broadcast input vec axis size[%zu] not equal output vec axis size[%zu]",
44	           input.vectorized_axis.size(), output.vectorized_axis.size());
45	    return af::FAILED;
46	  }
47	
48	  std::vector<uint32_t> tmp;
49	  ascir::SizeExpr prev_input_repeat = Zero;
50	  ascir::SizeExpr prev_output_repeat = Zero;
51	  size_t pos = 0;
52	
53	  for (; pos < input.vectorized_axis.size(); pos++) {
54	    ascir::SizeExpr input_stride = input.vectorized_strides[pos];
55	    ascir::SizeExpr output_stride = output.vectorized_strides[pos];
56	    if (af::SymbolicUtils::StaticCheckEq(input_stride, af::sym::kSymbolZero) == af::TriBool::kTrue &&
57	        af::SymbolicUtils::StaticCheckEq(output_stride, af::sym::kSymbolZero) == af::TriBool::kTrue) {
58	      continue;
59	    }
60	    prev_input_repeat = input.axis_size[input.vectorized_axis_pos[pos]];
61	    prev_output_repeat = output.axis_size[output.vectorized_axis_pos[pos]];
62	    break;
63	  }
64	
65	  if (pos >= input.vectorized_axis.size()) {
66	    return af::FAILED;
67	  }
68	
69	  tmp.push_back(pos);
70	  pos++;
71	  bool prev_status = af::SymbolicUtils::StaticCheckEq(prev_input_repeat, prev_output_repeat) != af::TriBool::kTrue;
72	  for (; pos < input.vectorized_axis.size(); pos++) {
73	    ascir::SizeExpr cur_input_stride = input.vectorized_strides[pos];
74	    ascir::SizeExpr cur_output_stride = output.vectorized_strides[pos];
75	    if (af::SymbolicUtils::StaticCheckEq(cur_input_stride, af::sym::kSymbolZero) == af::TriBool::kTrue &&
76	        af::SymbolicUtils::StaticCheckEq(cur_output_stride, af::sym::kSymbolZero) == af::TriBool::kTrue) {
77	      continue;
78	    }
79	    auto &cur_input_repeat = input.axis_size[input.vectorized_axis_pos[pos]];
80	    auto &cur_output_repeat = output.axis_size[output.vectorized_axis_pos[pos]];
81	    bool cur_status = af::SymbolicUtils::StaticCheckEq(cur_input_repeat, cur_output_repeat) != af::TriBool::kTrue;
82	    if (cur_status != prev_status) {
83	      broadcast_num = prev_status ? broadcast_num + 1 : broadcast_num;
84	      result.push_back({prev_status, tmp});
85	      tmp = {static_cast<uint32_t>(pos)};
86	      prev_status = cur_status;
87	    } else {
88	      tmp.push_back(pos);
89	    }
90	  }
91	  broadcast_num = prev_status ? broadcast_num + 1 : broadcast_num;
92	  result.push_back({prev_status, tmp});
93	  return af::SUCCESS;
94	}
