101	  if (is_brc_group && is_input) {
102	    return "1";
103	  }
104	  std::stringstream ss;
105	  for (size_t i = 0; i < merge_group.second.size(); i++) {
106	    GetOneAxisSize(tpipe, tensor, merge_group.second[i], ss);
107	    if (i != merge_group.second.size() - 1) {
108	      ss << " * ";
109	    }
110	  }
111	  return ss.str();
112	}
113	
114	static std::string GetLatterMergedSize(const TPipe &tpipe, const Tensor &tensor,
115	                                       const std::vector<std::pair<bool, std::vector<uint32_t>>> &merge_groups,
116	                                       const bool &is_input) {
117	  bool is_brc_group = merge_groups.back().first;
118	  if (is_brc_group && is_input) {
119	    return "1";
120	  }
121	  std::vector<uint32_t> last_group = merge_groups.back().second;
122	  uint32_t last_group_size = last_group.size();
123	  uint32_t idx = 0;
124	  if (last_group_size == static_cast<uint32_t>(1)) {
125	    // 最后一个分组只有一根轴，此时需要向前一个分组去借轴
126	    if (merge_groups.size() == 1) {
127	      return "0";
128	    }
129	    idx = merge_groups[merge_groups.size() - kAxisIndex2].second.back();
130	  } else {
131	    idx = last_group[last_group_size - kAxisIndex2];
132	  }
133	  ascir::SizeExpr last_dim_size = tensor.vectorized_strides[idx];
134	
135	  std::stringstream ss;
136	  uint32_t loop_extent = last_group_size - static_cast<uint32_t>(1);
137	  for (size_t i = 0; i < loop_extent; i++) {
138	    GetOneAxisSize(tpipe, tensor, last_group[i], ss);
139	    ss << " * ";
140	  }
141	  ss << tpipe.tiler.Size(last_dim_size);
142	  return ss.str();
143	}
144	
145	static std::string BroadcastGetLastDimStride(const TPipe &tpipe, const Tensor &tensor,
146	                                             const std::vector<std::pair<bool, std::vector<uint32_t>>> &merge_groups) {
147	  auto &last_merge_group = merge_groups.back();
148	  bool is_brc_group = last_merge_group.first;
149	  if (!is_brc_group) {
150	    return "1";
151	  }
152	  if (merge_groups.size() <= 1) {
153	    return "1";
154	  }
155	  auto &last_former_merge_group = merge_groups[merge_groups.size() - kAxisIndex2];
156	  uint32_t idx = last_former_merge_group.second.back();
157	  ascir::SizeExpr last_dim_stride = tensor.vectorized_strides[idx];
158	  return tpipe.tiler.Size(last_dim_stride);
159	}
160	
161	static void GetBroadcastSizeParameters(const TPipe &tpipe, const Tensor &tensor,
162	                                       const std::vector<std::pair<bool, std::vector<uint32_t>>> &merge_groups,
163	                                       const bool &is_input, std::vector<std::string> &repeat_sizes) {
164	  for (size_t i = 0; i < merge_groups.size(); i++) {
165	    if (i != merge_groups.size() - 1) {
166	      repeat_sizes[i] = GetFormerMergedSize(tpipe, tensor, merge_groups[i], is_input);
167	    } else {
168	      repeat_sizes[i] = GetLatterMergedSize(tpipe, tensor, merge_groups, is_input);
169	    }
170	  }
171	}
172	
173	static void BroadcastAllCommonAxis(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis,
174	                                   const Tensor &input, const Tensor &output, std::string &result) {
175	  std::stringstream ss;
176	  std::string dtype_name;
177	  Tensor::DtypeName(output.dtype, dtype_name);
178	  ss << "DataCopy(" << output << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, output) << "], " << input
179	     << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, input) << "], " << KernelUtils::SizeAlign() << "("
180	     << output.actual_size << ", 32 / sizeof(" << dtype_name << "))"
181	     << ");" << std::endl;
182	  result = ss.str();
183	}
184	
185	static void BroadcastOneAxis(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis, const Tensor &input,
186	                             const Tensor &output, const int64_t tmp_buf_id,
187	                             const std::vector<std::pair<bool, std::vector<uint32_t>>> &merge_groups,
188	                             std::string &result) {
189	  std::vector<std::string> src_size = {"0", "0", "0"};
190	  std::vector<std::string> dst_size = {"0", "0", "0"};
191	  GetBroadcastSizeParameters(tpipe, output, merge_groups, true, src_size);
192	  GetBroadcastSizeParameters(tpipe, output, merge_groups, false, dst_size);
193	  std::string last_dim_stride = BroadcastGetLastDimStride(tpipe, input, merge_groups);
194	  std::stringstream ss;
195	  ss << "Broadcast(" << output << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, output) << "], " << input
196	     << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, input) << "], " << src_size[kAxisIndex0] << ", "
197	     << src_size[kAxisIndex1] << ", " << src_size[kAxisIndex2] << ", " << dst_size[kAxisIndex0] << ", "
198	     << dst_size[kAxisIndex1] << ", " << dst_size[kAxisIndex2] << ", " << tpipe.tmp_buf << "_"
199	     << std::to_string(tmp_buf_id) << ", " << last_dim_stride << ");" << std::endl;
200	  result = ss.str();
201	}
202	
203	static void BroadcastTwoAxis(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis, const Tensor &input,
204	                             const Tensor &output, const int64_t tmp_buf_id,
205	                             const std::vector<std::pair<bool, std::vector<uint32_t>>> &merge_groups,
206	                             std::string &result) {
207	  const auto vectorize_axis_size = merge_groups.size();
208	  std::vector<std::string> src_size(vectorize_axis_size, "0");
209	  std::vector<std::string> dst_size(vectorize_axis_size, "0");
210	  GetBroadcastSizeParameters(tpipe, output, merge_groups, true, src_size);
211	  GetBroadcastSizeParameters(tpipe, output, merge_groups, false, dst_size);
212	  std::string last_dim_stride = BroadcastGetLastDimStride(tpipe, input, merge_groups);
213	  if (vectorize_axis_size == kAxisSizeThree) {
214	    src_size.insert(src_size.begin(), "1");
215	    dst_size.insert(dst_size.begin(), "1");
216	  }
217	  std::stringstream ss;
218	  ss << "Broadcast(" << output << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, output) << "], " << input
219	     << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, input) << "], " << src_size[kAxisIndex0] << ", "
220	     << src_size[kAxisIndex1] << ", " << src_size[kAxisIndex2] << ", " << src_size[kAxisIndex3] << ", "
221	     << dst_size[kAxisIndex0] << ", " << dst_size[kAxisIndex1] << ", " << dst_size[kAxisIndex2] << ", "
222	     << dst_size[kAxisIndex3] << ", " << tpipe.tmp_buf << "_" << std::to_string(tmp_buf_id) << ", " << last_dim_stride
223	     << ");" << std::endl;
224	  result = ss.str();
225	}
226	
227	bool IsBroadcastConstantTensor(const Tensor &tensor) {
228	  if (tensor.is_constant) {
229	    return true;
230	  }
231	  bool tensor_constant = true;
232	  for (size_t i = 0; i < tensor.vectorized_axis.size(); i++) {
233	    auto &src_repeat = tensor.axis_size[tensor.vectorized_axis_pos[i]];
234	    if (af::SymbolicUtils::StaticCheckEq(src_repeat, af::sym::kSymbolOne) != af::TriBool::kTrue) {
235	      tensor_constant = false;
236	      break;
237	    }
238	  }
239	  return tensor_constant;
240	}
241	
242	void BroadcastScalar(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis, const Tensor &in,
243	                     const Tensor &out, const int64_t tmp_buf_id, std::string &result, bool need_tmp_buf) {
244	  std::stringstream ss;
245	  std::string int64_tmp_buf;
246	  if ((in.dtype == ge::DT_INT64 || in.dtype == ge::DT_UINT64) && need_tmp_buf) {
247	    int64_tmp_buf = ", " + tpipe.tmp_buf.name + "_" + std::to_string(tmp_buf_id);
248	  }
249	  if (in.is_constant) {
250	    ss << "Duplicate(" << out << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, out) << "], " << in.name
251	       << ", " << out.actual_size << int64_tmp_buf << ");" << std::endl;
252	  } else if (in.is_ub_scalar) {
253	    ss << "Duplicate(" << out << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, out) << "], "
254	       << in.ub_scalar_name << ", " << out.actual_size << int64_tmp_buf << ");" << std::endl;
255	  } else {
256	    if (in.position == af::Position::kPositionVecIn) {
257	      std::string event_id = in.name + "_event_id";
258	      ss << "event_t " << event_id << " = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE2_S));"
259	         << std::endl;
260	      ss << "SetFlag<HardEvent::MTE2_S>(" << event_id << ");" << std::endl;
261	      ss << "WaitFlag<HardEvent::MTE2_S>(" << event_id << ");" << std::endl;
262	    } else if (in.position == af::Position::kPositionVecCalc) {
263	      std::string event_id = in.name + "_event_id";
264	      ss << "event_t " << event_id << " = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_S));"
265	         << std::endl;
266	      ss << "SetFlag<HardEvent::V_S>(" << event_id << ");" << std::endl;
267	      ss << "WaitFlag<HardEvent::V_S>(" << event_id << ");" << std::endl;
268	    }
269	    ss << "Duplicate(" << out << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, out) << "], " << in
270	       << ".GetValue(0), " << out.actual_size << int64_tmp_buf << ");" << std::endl;
271	  }
272	  result = ss.str();
273	}
274	
275	Status BroadcastApiCall::Generate(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis,
276	                                  const std::vector<std::reference_wrapper<const Tensor>> &inputs,
277	                                  const std::vector<std::reference_wrapper<const Tensor>> &outputs,
278	                                  std::string &result) const {
279	  const auto &x = inputs[0].get();
280	  const auto &y = outputs[0].get();
281	  // 获取tmp_buf复用TBuf的id
282	  int64_t life_time_axis_id = -1L;
283	  int64_t id = -1L;
284	  auto it = this->tmp_buf_id.find(life_time_axis_id);
285	  if (it != this->tmp_buf_id.end()) {
286	    id = it->second;
287	  }
288	
289	  (void)RegisterBasicDumpParam(this->api_name_, inputs, outputs, {}, tpipe.tmp_buf.name + "_" + std::to_string(id));
290	
291	  // 处理scalar broadcast场景
292	  if (IsBroadcastConstantTensor(x)) {
293	    GE_ASSERT_TRUE(id != -1L, "BroadcastApiCall cannot find tmp buffer id to use.");
294	    BroadcastScalar(tpipe, current_axis, x, y, id, result);
295	    return af::SUCCESS;
296	  }
297	
298	  std::vector<std::pair<bool, std::vector<uint32_t>>> merge_groups;
299	  uint32_t broadcast_num = 0;
300	  Status status = DimensionCollapse(x, y, merge_groups, broadcast_num);
301	  if (status != af::SUCCESS) {
302	    GELOGE(af::FAILED, "BroadcastApiCall do dimension collapse failed.");
303	    return af::FAILED;
304	  }
305	
306	  // ub内没有broadcast轴，这种场景下，Schedule会删除无效的broadcast节点
307	  // 为了防止异常场景，依然保留这种特殊处理逻辑
308	  if (broadcast_num == static_cast<uint32_t>(0)) {
309	    BroadcastAllCommonAxis(tpipe, current_axis, x, y, result);
310	    return af::SUCCESS;
311	  }
312	
313	  if (broadcast_num == static_cast<uint32_t>(1)) {
314	    GE_ASSERT_TRUE(id != -1L, "BroadcastApiCall cannot find tmp buffer id to use.");
315	    BroadcastOneAxis(tpipe, current_axis, x, y, id, merge_groups, result);
316	    return af::SUCCESS;
317	  }
318	
319	  if (broadcast_num == kDoubleAxisSize &&
320	      (merge_groups.size() == kAxisSizeThree || merge_groups.size() == kAxisSizeFour)) {
321	    GE_ASSERT_TRUE(id != -1L, "BroadcastApiCall cannot find tmp buffer id to use.");
322	    BroadcastTwoAxis(tpipe, current_axis, x, y, id, merge_groups, result);
323	    return af::SUCCESS;
324	  }
325	
326	  GELOGE(af::FAILED, "BroadcastApiCall don't support multi discontinuous broadcast axis.");
327	  GELOGE(af::FAILED, "x_t_name:%s, axis_id:%s, size:%s, strides:%s, v_axis_id:%s, v_axis_pos:%s, v_strides:%s",
328	         x.name.c_str(), VectorToStr(x.axis).c_str(), VectorToStr(x.axis_size).c_str(),
329	         VectorToStr(x.axis_strides).c_str(), VectorToStr(x.vectorized_axis).c_str(),
330	         VectorToStr(x.vectorized_axis_pos).c_str(), VectorToStr(x.vectorized_strides).c_str());
331	  GELOGE(af::FAILED, "y_t_name:%s, axis_id:%s, size:%s, strides:%s, v_axis_id:%s, v_axis_pos:%s, v_strides:%s",
332	         y.name.c_str(), VectorToStr(y.axis).c_str(), VectorToStr(y.axis_size).c_str(),
333	         VectorToStr(y.axis_strides).c_str(), VectorToStr(y.vectorized_axis).c_str(),
334	         VectorToStr(y.vectorized_axis_pos).c_str(), VectorToStr(y.vectorized_strides).c_str());
335	  return af::FAILED;
336	}
337	static ApiCallRegister<BroadcastApiCall> register_broadcast_api_call("BroadcastApiCall");
338	}  // namespace codegen
